{
  "query": "query GetTranscripts($date: DateTime) { transcripts(date: $date) { id title participants { name email } date duration } }",
  "variables": {
    "date": "{{ new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString() }}"
  }
}

{
  "query": "query GetTranscript($transcriptId: String!) { transcript(id: $transcriptId) { id title transcript sentences { text start_time end_time speaker_name } participants { name email } date duration } }",
  "variables": {
    "transcriptId": "{{ $json.id }}"
  }
}

