// Prepare email data from AI analysis
const aiResponse = $input.first().json;
const meetingData = $input.last().json;

// Parse AI response (assuming it's JSON)
let analysis;
try {
  if (typeof aiResponse.output === 'string') {
    analysis = JSON.parse(aiResponse.output);
  } else {
    analysis = aiResponse.output || aiResponse;
  }
} catch (e) {
  analysis = {
    dealStatus: 'unknown',
    probability: 0,
    buyingSignals: [],
    objections: [],
    actionItems: [],
    sentiment: 'neutral',
    keyTopics: [],
    decisionMakers: [],
    recommendations: ['Review transcript manually'],
    urgency: 'medium',
    summary: 'AI analysis failed - please review transcript manually'
  };
}

// Format meeting details
const meetingTitle = meetingData.title || 'Untitled Meeting';
const participants = meetingData.participants || [];
const duration = Math.round((meetingData.duration || 0) / 60);
const meetingDate = new Date(meetingData.date).toLocaleString();

// Create email subject
const probability = analysis.probability || 0;
const dealStatus = analysis.dealStatus || 'unknown';
const subject = `🚀 Sales Meeting: ${meetingTitle} - ${dealStatus.charAt(0).toUpperCase() + dealStatus.slice(1)} (${probability}% probability)`;

// Create HTML email content
const htmlContent = `
  <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
    <h1 style="color: #333; border-bottom: 2px solid #007bff; padding-bottom: 10px;">Sales Meeting Intelligence Report</h1>

    <div style="background-color: #f8f9fa; padding: 15px; border-radius: 5px; margin: 20px 0;">
      <h2 style="margin-top: 0; color: #495057;">Meeting Overview</h2>
      <p><strong>Title:</strong> ${meetingTitle}</p>
      <p><strong>Participants:</strong> ${participants.map(p => p.name).join(', ')}</p>
      <p><strong>Duration:</strong> ${duration} minutes</p>
      <p><strong>Date:</strong> ${meetingDate}</p>
    </div>

    <div style="background-color: #e3f2fd; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #2196f3;">
      <h2 style="margin-top: 0; color: #0d47a1;">Deal Status & Probability</h2>
      <p style="font-size: 18px; font-weight: bold; color: ${probability >= 80 ? '#4caf50' : probability >= 50 ? '#ff9800' : '#f44336'};">Status: ${dealStatus.charAt(0).toUpperCase() + dealStatus.slice(1)} | Probability: ${probability}%</p>
      <p><strong>Summary:</strong> ${analysis.summary || 'No summary available'}</p>
    </div>

    ${analysis.buyingSignals && analysis.buyingSignals.length > 0 ? `
    <div style="background-color: #e8f5e8; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #4caf50;">
      <h3 style="margin-top: 0; color: #2e7d32;">✅ Buying Signals</h3>
      <ul>
        ${analysis.buyingSignals.map(signal => `<li>${signal}</li>`).join('')}
      </ul>
    </div>
    ` : ''}

    ${analysis.objections && analysis.objections.length > 0 ? `
    <div style="background-color: #ffebee; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #f44336;">
      <h3 style="margin-top: 0; color: #c62828;">⚠️ Objections & Concerns</h3>
      <ul>
        ${analysis.objections.map(obj => `<li>${obj}</li>`).join('')}
      </ul>
    </div>
    ` : ''}

    ${analysis.actionItems && analysis.actionItems.length > 0 ? `
    <div style="background-color: #fff3e0; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #ff9800;">
      <h3 style="margin-top: 0; color: #e65100;">📋 Action Items</h3>
      <ul>
        ${analysis.actionItems.map(item => `<li>${item}</li>`).join('')}
      </ul>
    </div>
    ` : ''}

    <div style="background-color: #f3e5f5; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #9c27b0;">
      <h3 style="margin-top: 0; color: #7b1fa2;">🎯 AI Recommendations</h3>
      <p><strong>Urgency:</strong> <span style="color: ${analysis.urgency === 'high' ? '#f44336' : analysis.urgency === 'medium' ? '#ff9800' : '#4caf50'}; font-weight: bold;">${analysis.urgency.charAt(0).toUpperCase() + analysis.urgency.slice(1)}</span></p>
      <ul>
        ${analysis.recommendations ? analysis.recommendations.map(rec => `<li>${rec}</li>`).join('') : '<li>No specific recommendations provided</li>'}
      </ul>
    </div>

    ${analysis.keyTopics && analysis.keyTopics.length > 0 ? `
    <div style="background-color: #e0f2f1; padding: 15px; border-radius: 5px; margin: 20px 0; border-left: 4px solid #009688;">
      <h3 style="margin-top: 0; color: #00695c;">💬 Key Topics Discussed</h3>
      <ul>
        ${analysis.keyTopics.map(topic => `<li>${topic}</li>`).join('')}
      </ul>
    </div>
    ` : ''}

    <div style="margin-top: 30px; padding-top: 20px; border-top: 1px solid #dee2e6; color: #6c757d; font-size: 12px;">
      <p>This analysis was generated automatically by AI from the meeting transcript. Please review and follow up accordingly.</p>
      <p><em>Generated by Fireflies AI Sales Intelligence System</em></p>
    </div>
  </div>
`;

return {
  subject: subject,
  htmlContent: htmlContent,
  meetingTitle: meetingTitle,
  analysis: analysis,
  meetingData: meetingData
};

// Extract transcripts array from GraphQL response
const response = $input.first().json;

// Handle Fireflies GraphQL response structure
let transcripts = [];
if (response.data && response.data.transcripts) {
  transcripts = response.data.transcripts;
} else if (response.transcripts) {
  transcripts = response.transcripts;
} else if (Array.isArray(response)) {
  transcripts = response;
}

// Filter out any transcripts that might be duplicates or already processed
// For now, return all - in production you might want to track processed IDs
return transcripts;

// Extract transcript data from GraphQL response
const response = $input.first().json;

// Handle Fireflies GraphQL response structure
let transcriptData = {};
if (response.data && response.data.transcript) {
  transcriptData = response.data.transcript;
} else if (response.transcript) {
  transcriptData = response.transcript;
} else {
  transcriptData = response;
}

// Format transcript text from sentences array
let transcriptText = '';
if (transcriptData.sentences && Array.isArray(transcriptData.sentences)) {
  transcriptText = transcriptData.sentences.map(sentence => 
    `${sentence.speaker_name}: ${sentence.text}`
  ).join('\n');
} else if (transcriptData.transcript) {
  transcriptText = transcriptData.transcript;
}

// Return formatted data for AI analysis
return {
  id: transcriptData.id,
  title: transcriptData.title || 'Untitled Meeting',
  transcript: transcriptText,
  participants: transcriptData.participants || [],
  date: transcriptData.date,
  duration: transcriptData.duration || 0
};
